import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardActionArea, CardMedia, CardContent, Typography, Grid, Button } from '@mui/material';

const templates = [
  { key: 'classic', name: 'Classic', description: 'Professional and traditional layout' },
  { key: 'modern', name: 'Modern', description: 'Clean and contemporary design' },
  { key: 'minimal', name: 'Minimal', description: 'Simple and elegant style' },
  { key: 'creative', name: 'Creative', description: 'Unique and eye-catching design' },
];

function TemplateGallery() {
  const navigate = useNavigate();
  const handleSelect = (key) => {
    localStorage.setItem('selectedTemplate', key);
    navigate('/builder');
  };
  return (
    <div className="template-gallery">
      <h2>Choose Your Resume Template</h2>
      <Grid container spacing={3} justifyContent="center" sx={{ mt: 2 }}>
        {templates.map((template) => (
          <Grid item key={template.key} xs={12} sm={6} md={3}>
            <Card sx={{ border: localStorage.getItem('selectedTemplate') === template.key ? '2px solid #1976d2' : 'none', boxShadow: localStorage.getItem('selectedTemplate') === template.key ? 6 : 1 }}>
              <CardActionArea onClick={() => handleSelect(template.key)}>
                <CardMedia
                  component="img"
                  height="180"
                  image={`/images/templates/${template.key}.jpg`}
                  alt={template.name}
                />
                <CardContent>
                  <Typography variant="h6" align="center">{template.name}</Typography>
                </CardContent>
              </CardActionArea>
              <Button
                variant={localStorage.getItem('selectedTemplate') === template.key ? 'contained' : 'outlined'}
                color="primary"
                fullWidth
                onClick={() => handleSelect(template.key)}
                sx={{ borderRadius: 0 }}
              >
                {localStorage.getItem('selectedTemplate') === template.key ? 'Selected' : 'Select'}
              </Button>
            </Card>
          </Grid>
        ))}
      </Grid>
    </div>
  );
}

export default TemplateGallery;
